mapper.select:
SELECT t1.DATA_UUID AS dataUuid, t1.DATA_ID AS dataId, t3.RULE_ID AS ruleId, t3.PBC_ASSET_CODE AS pbcElementCode, t3.TABLE_DATA_NAME AS reportName, t3.CHECKED_FIELD_NAME AS fieldName, t3.RULE_TYPE AS ruleType, t3.RULE_IDENTIFY AS ruleCode, t3.RULE_CONTENT AS ruleDetails, t1.ORG_DATA AS orgData, t1.CHECK_DATE AS checkDate, t2.CHECK_RESULT AS checkResult, t1.RELEVANCE_REPORT AS relevanceReport, t2.CHECK_FLAG AS checkFlag FROM pbc_submit_before_check t1 LEFT JOIN pbc_generat_b_checkdetail t2 ON t1.DATA_UUID = t2.CHECK_UUID LEFT JOIN pbc_check_rule_info t3 ON t3.RULE_ID = t2.RULE_ID
t2.CHECK_FLAG = '1'
AND DATE_FORMAT(t1.CHECK_DATE, '%Y-%m-%d') >= #{checkDateStart,jdbcType=VARCHAR}
AND DATE_FORMAT(t1.CHECK_DATE, '%Y-%m-%d') <= #{checkDateEnd,jdbcType=VARCHAR}
#{item,jdbcType=VARCHAR}
AND t3.CHECKED_FIELD_NAME LIKE CONCAT('%',CONCAT(#{fieldName,jdbcType=VARCHAR},'%'))
#{item,jdbcType=VARCHAR}
AND t3.RULE_IDENTIFY = #{ruleCode,jdbcType=VARCHAR}
AND t3.RULE_ID LIKE CONCAT('%',CONCAT(#{ruleId,jdbcType=VARCHAR},'%'))
AND t2.CHECK_FLAG = #{checkFlag,jdbcType=VARCHAR}

mapper.insert:
insert into pbc_submit_before_check(DATA_UUID, DATA_ID, RULE_ID, PBC_ELEMENT_CODE, REPORT_NAME, FIELD_NAME, RULE_TYPE, RULE_CODE, RULE_DETAILS, ORG_DATA, CHECK_DATE, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME, ERR_MSG, RELEVANCE_REPORT, FLAG_UUID) select DATA_UUID, DATA_ID, RULE_ID, PBC_ELEMENT_CODE, REPORT_NAME, FIELD_NAME, RULE_TYPE, RULE_CODE, RULE_DETAILS, ORG_DATA, CHECK_DATE, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME, ERR_MSG, RELEVANCE_REPORT, FLAG_UUID from ( select TEMP.* from (
SELECT #{dataUuid,jdbcType=VARCHAR} DATA_UUID, #{dataId,jdbcType=VARCHAR} DATA_ID, #{ruleId,jdbcType=VARCHAR} RULE_ID, #{pbcElementCode,jdbcType=VARCHAR} PBC_ELEMENT_CODE, #{reportName,jdbcType=VARCHAR} REPORT_NAME, #{fieldName,jdbcType=VARCHAR} FIELD_NAME, #{ruleType,jdbcType=VARCHAR} RULE_TYPE, #{ruleCode,jdbcType=VARCHAR} RULE_CODE, #{ruleDetails,jdbcType=VARCHAR} RULE_DETAILS, #{orgData,jdbcType=LONGVARCHAR} ORG_DATA, #{checkDate,jdbcType=TIMESTAMP} CHECK_DATE, #{createUser,jdbcType=VARCHAR} CREATE_USER, #{createDept,jdbcType=VARCHAR} CREATE_DEPT, #{createTime,jdbcType=TIMESTAMP} CREATE_TIME, #{updateUser,jdbcType=VARCHAR} UPDATE_USER, #{updateTime,jdbcType=TIMESTAMP} UPDATE_TIME, #{errMsg,jdbcType=LONGVARCHAR} ERR_MSG, #{relevanceReport,jdbcType=VARCHAR} RELEVANCE_REPORT, #{flagUuid,jdbcType=VARCHAR} FLAG_UUID FROM DUAL
) TEMP where not exists (select 1 from pbc_submit_before_check CII where CII.DATA_ID = TEMP.DATA_ID) ) de ;
UPDATE pbc_submit_before_check as A, ( select DATA_UUID, DATA_ID, RULE_ID, PBC_ELEMENT_CODE, REPORT_NAME, FIELD_NAME, RULE_TYPE, RULE_CODE, RULE_DETAILS, ORG_DATA, CHECK_DATE, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME, ERR_MSG, RELEVANCE_REPORT, FLAG_UUID from ( select TEMP.* from (
SELECT #{dataUuid,jdbcType=VARCHAR} DATA_UUID, #{dataId,jdbcType=VARCHAR} DATA_ID, #{ruleId,jdbcType=VARCHAR} RULE_ID, #{pbcElementCode,jdbcType=VARCHAR} PBC_ELEMENT_CODE, #{reportName,jdbcType=VARCHAR} REPORT_NAME, #{fieldName,jdbcType=VARCHAR} FIELD_NAME, #{ruleType,jdbcType=VARCHAR} RULE_TYPE, #{ruleCode,jdbcType=VARCHAR} RULE_CODE, #{ruleDetails,jdbcType=VARCHAR} RULE_DETAILS, #{orgData,jdbcType=LONGVARCHAR} ORG_DATA, #{checkDate,jdbcType=TIMESTAMP} CHECK_DATE, #{createUser,jdbcType=VARCHAR} CREATE_USER, #{createDept,jdbcType=VARCHAR} CREATE_DEPT, #{createTime,jdbcType=TIMESTAMP} CREATE_TIME, #{updateUser,jdbcType=VARCHAR} UPDATE_USER, #{updateTime,jdbcType=TIMESTAMP} UPDATE_TIME, #{errMsg,jdbcType=LONGVARCHAR} ERR_MSG, #{relevanceReport,jdbcType=VARCHAR} RELEVANCE_REPORT, #{flagUuid,jdbcType=VARCHAR} FLAG_UUID FROM DUAL
) TEMP ) de ) AS B set A.* = B.* where exists ( select 1 from pbc_submit_before_check CII where CII.DATA_ID = TEMP.DATA_ID);

mapper.delete:
delete from pbc_submit_before_check
where DATA_ID = #{dataId,jdbcType=VARCHAR}
and REPORT_NAME = #{reportName,jdbcType=VARCHAR}
